CREATE TABLE gateway_recoveries (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
    tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    workspace_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    request_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    requested_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    reason VARCHAR(500) NOT NULL CHECK(CHAR_LENGTH(reason)>0),
    idempotency_key CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    fingerprint VARBINARY(32) NOT NULL CHECK(OCTET_LENGTH(fingerprint)=32),
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    expires_at DATETIME(6) NOT NULL,
    superseded_at DATETIME(6),
    invalidated_at DATETIME(6),
    fence_receipt JSON CHECK(fence_receipt IS NULL OR JSON_TYPE(fence_receipt)='OBJECT' AND OCTET_LENGTH(CAST(fence_receipt AS CHAR CHARACTER SET utf8mb4))<=4096),
    fence_receipt_sha256 VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin CHECK(fence_receipt_sha256 IS NULL OR REGEXP_LIKE(fence_receipt_sha256,'^[a-f0-9]{64}$','c')),
    fence_accepted_at DATETIME(6),
    fence_accepted_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    confirmed_at DATETIME(6),
    confirmation_fingerprint VARBINARY(32) CHECK(confirmation_fingerprint IS NULL OR OCTET_LENGTH(confirmation_fingerprint)=32),
    confirmed_deployment_revision BIGINT CHECK(confirmed_deployment_revision IS NULL OR confirmed_deployment_revision BETWEEN 1 AND 9007199254740991),
    UNIQUE(tenant_id,workspace_id,request_id,id),
    UNIQUE(tenant_id,workspace_id,request_id,requested_by,idempotency_key),
    KEY gateway_recovery_request_idx(tenant_id,workspace_id,request_id,created_at DESC,id DESC),
    CONSTRAINT gateway_recovery_actor_fk FOREIGN KEY(requested_by) REFERENCES users(id),
    CONSTRAINT gateway_recovery_fence_actor_fk FOREIGN KEY(fence_accepted_by) REFERENCES users(id),
    CONSTRAINT gateway_recovery_request_scope_fk FOREIGN KEY(tenant_id,workspace_id,request_id) REFERENCES gateway_requests(tenant_id,workspace_id,id),
    CONSTRAINT gateway_recovery_expiry_order CHECK(expires_at>created_at),
    CONSTRAINT gateway_recovery_receipt_shape CHECK((fence_receipt IS NULL AND fence_receipt_sha256 IS NULL AND fence_accepted_at IS NULL AND fence_accepted_by IS NULL) OR (fence_receipt IS NOT NULL AND fence_receipt_sha256 IS NOT NULL AND fence_accepted_at IS NOT NULL AND fence_accepted_by IS NOT NULL)),
    CONSTRAINT gateway_recovery_confirmation_shape CHECK((confirmed_at IS NULL AND confirmation_fingerprint IS NULL AND confirmed_deployment_revision IS NULL) OR (confirmed_at IS NOT NULL AND fence_accepted_at IS NOT NULL AND confirmation_fingerprint IS NOT NULL AND confirmed_deployment_revision IS NOT NULL)),
    CONSTRAINT gateway_recoveries_id_canonical CHECK(id IS NULL OR REGEXP_LIKE(id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_recoveries_tenant_id_canonical CHECK(tenant_id IS NULL OR REGEXP_LIKE(tenant_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_recoveries_workspace_id_canonical CHECK(workspace_id IS NULL OR REGEXP_LIKE(workspace_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_recoveries_request_id_canonical CHECK(request_id IS NULL OR REGEXP_LIKE(request_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_recoveries_requested_by_canonical CHECK(requested_by IS NULL OR REGEXP_LIKE(requested_by,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_recoveries_idempotency_key_canonical CHECK(idempotency_key IS NULL OR REGEXP_LIKE(idempotency_key,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_recoveries_fence_accepted_by_canonical CHECK(fence_accepted_by IS NULL OR REGEXP_LIKE(fence_accepted_by,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
